// MoonProof data layer: every value travels with its origin and state.
// Static NASA-derived products come from web/data/ (loaded with web/lab/ modules, not copied);
// the API uses the shared deployment-aware URL resolver; absence is shown, never hidden.
// Source of truth: this .ts file. data.js is generated by `npm --prefix web run build:ts`.
// The three imports below are untyped JS modules (no declaration files): their bindings are `any`.
import { SiteSeries, HOUR_MS } from "../../lab/data.js";
import { TerrainGrid } from "../../lab/terrain.js";
import { apiURL } from "../../api-base.js";
export { apiBase } from "../../api-base.js";
export const DATA_BASE = new URL("../../data/", import.meta.url).href;
export const SEALS = ["VAL", "PRE", "EST", "SIM", "N/D", "FALHA"];
/**
 * Map an origin state to a seal. VAL is returned ONLY for the exact state "VALIDATED".
 * PRELIMINARY_* → PRE, SYNTHETIC → SIM, UNVERIFIED_INPUTS → EST, NO_SERIES_DATA/missing → N/D, ERROR → FALHA.
 */
export function sealFor(status) {
    const s = String(status || "").toUpperCase();
    if (s === "VALIDATED")
        return "VAL";
    if (s.startsWith("PRELIMINARY"))
        return "PRE";
    if (s === "SYNTHETIC" || s.includes("SYNTHETIC") || s === "SIMULATION")
        return "SIM";
    if (s === "UNVERIFIED_INPUTS" || s === "ESTIMATE")
        return "EST";
    if (s === "ERROR" || s === "FAILED")
        return "FALHA";
    return "N/D";
}
/**
 * A value with provenance. Missing/non-finite value → seal N/D (never 0).
 * { value, unit, status, seal, source, detail }  — detail is free text for the Proof layer.
 */
export function sourced(value, { unit = "", status, source = "", detail = {} } = {}) {
    const missing = value == null || (typeof value === "number" && !Number.isFinite(value));
    return Object.freeze({ value: missing ? null : value, unit, status: missing ? (status === "ERROR" ? "ERROR" : "NO_DATA") : status,
        seal: missing ? (status === "ERROR" ? "FALHA" : "N/D") : sealFor(status), source, detail });
}
let sitesP = null;
/** The five real sites of web/data/sites.json, numbered 1..n in file order. */
export function loadSites() {
    return sitesP ||= fetch(DATA_BASE + "sites.json").then(r => { if (!r.ok)
        throw new Error("sites.json " + r.status); return r.json(); })
        .then(doc => ({ status: doc.science_status, note: doc.note, window: doc.series_window, generated: doc.generated_utc, features: doc.features || [],
        sites: doc.sites.map((s, i) => ({ ...s, n: i + 1 })) }));
}
/** Long-term metric of a site as a sourced value (from sites.json metrics). */
export function siteMetric(doc, site, key, unit) {
    return sourced(site?.metrics?.[key], { unit, status: doc.status,
        source: "web/data/sites.json · metrics." + key, detail: { window: doc.window, generated: doc.generated } });
}
/** Tolerance of the science review against NASA PGDA (docs/SCIENCE_REVIEW_ONBOARD_BS061.md, section 2.2). */
export const PGDA_SUN_TOLERANCE_PP = 5;
/**
 * null, or why the sunlight figures of a site are to be read as an upper bound: our series shows more
 * sunlight than the NASA PGDA average map by more than the tolerance. Decided from sites.json alone
 * (metrics.mean_solar_disc_visible_pct against pgda_sun_pct), never from a site id.
 */
export function sunCaveat(site) {
    const ours = site?.metrics?.mean_solar_disc_visible_pct, pgda = site?.pgda_sun_pct;
    if (typeof ours !== "number" || typeof pgda !== "number" || !Number.isFinite(ours) || !Number.isFinite(pgda) || ours - pgda <= PGDA_SUN_TOLERANCE_PP)
        return null;
    return Object.freeze({ kind: "SUN_UPPER_BOUND", ours, pgda, diff: ours - pgda });
}
const seriesCache = new Map();
export function loadSeries(site) {
    // SiteSeriesLike is the screens' loose view of SiteSeries (a NOT_COMPUTED window carries no metrics), hence the cast.
    if (!seriesCache.has(site.id))
        seriesCache.set(site.id, SiteSeries.load(DATA_BASE + site.series));
    return seriesCache.get(site.id);
}
/** Window metrics for [startIso, +hours) from the stored hourly series, each value sourced. */
export async function windowMetrics(doc, site, startIso, hours) {
    const series = await loadSeries(site);
    const t0 = startIso ? Date.parse(startIso) : series.start;
    const w = series.window(t0, hours);
    const st = w.status === "COMPUTED" ? doc.status : "NO_SERIES_DATA";
    const base = { status: st, source: "web/data/" + site.series + ".bin", detail: { sha256: series.meta.series.sha256, start: new Date(t0).toISOString(), hours, step: "1 h" } };
    return { raw: w, series, t0,
        sunPct: sourced(w.sunPct, { ...base, unit: "%" }), earthPct: sourced(w.earthPct, { ...base, unit: "%" }),
        longestDarkH: sourced(w.longestDarkH, { ...base, unit: "h" }), longestBlackoutH: sourced(w.longestBlackoutH, { ...base, unit: "h" }),
        maxSunElDeg: sourced(w.maxSunElDeg, { ...base, unit: "°" }) };
}
/** Same aggregate contract as windowMetrics, using the API when available. The
 * browser series is still the source of per-hour traces and daily charts. */
export async function apiWindowMetrics(doc, site, startIso, hours) {
    const base = await windowMetrics(doc, site, startIso, hours);
    const t0iso = new Date(base.t0).toISOString().replace(".000Z", "Z");
    const r = await api("/api/compare", { method: "POST", body: { site_ids: [site.id], start_utc: t0iso, duration_hours: hours } });
    const x = r.ok ? r.data?.results?.[0] : undefined, m = x?.evaluation?.metrics;
    if (!x || x.data_status !== "AVAILABLE" || !m)
        return { ...base, origin: "static" };
    const info = { status: x.science_status, source: "POST /api/compare", detail: { sha256: x.site?.series_sha256 ?? null, start: t0iso, hours, step: "1 h" } };
    const pct = (f) => (typeof f === "number" && Number.isFinite(f) ? 100 * f : null);
    return { ...base, origin: "api",
        sunPct: sourced(pct(m.sun_visible_fraction), { ...info, unit: "%" }), earthPct: sourced(pct(m.earth_visible_fraction), { ...info, unit: "%" }),
        longestDarkH: sourced(m.longest_continuous_dark_hours, { ...info, unit: "h" }), longestBlackoutH: sourced(m.longest_continuous_comm_gap_hours, { ...info, unit: "h" }) };
}
/** Per-day sunlit fraction (0..1) over the window, for the "Why" bar. */
export function dailySun(series, t0, hours) {
    const out = [];
    const i0 = Math.ceil((t0 - series.start) / HOUR_MS);
    for (let d = 0; d * 24 < hours; d++) {
        let on = 0, n = 0;
        for (let h = d * 24; h < Math.min(hours, d * 24 + 24); h++) {
            const i = i0 + h;
            if (i < 0 || i >= series.count)
                continue;
            n++;
            if (series.sunMargin[i] >= 0)
                on++;
        }
        out.push(n ? on / n : null);
    }
    return out;
}
let gridP = null;
export function loadRegion() { return gridP ||= TerrainGrid.load(DATA_BASE + "region/south_pole_400m"); }
/**
 * Call the API. Resolves {ok:true, data, status} or {ok:false, offline, httpStatus, code, error}. Never throws.
 * status is the payload's own science state when present (science_status / status / state).
 */
export async function api(path, { method = "GET", body, timeoutMs = 8000, as = "json" } = {}) {
    const ctl = new AbortController();
    const tm = setTimeout(() => ctl.abort(), timeoutMs);
    try {
        const r = await fetch(apiURL(path), { method, signal: ctl.signal,
            headers: body ? { "content-type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined });
        if (!r.ok) {
            const payload = await r.json().catch(() => null);
            const code = typeof payload?.code === "string" ? payload.code : null;
            return { ok: false, offline: r.status >= 500, httpStatus: r.status, code, error: "HTTP " + r.status + (code ? " · " + code : "") };
        }
        if (as === "text") {
            if (!/^text\/html(?:;|$)/i.test(r.headers.get("content-type") || ""))
                return { ok: false, offline: false, httpStatus: r.status, error: "INVALID_REPORT_TYPE" };
            return { ok: true, data: await r.text(), status: null };
        }
        const data = await r.json();
        return { ok: true, data, status: data?.science_status || data?.status || data?.state || null };
    }
    catch (e) {
        return { ok: false, offline: true, error: String(e?.message || e) };
    }
    finally {
        clearTimeout(tm);
    }
}
/** true when /readyz answers. Screens show "offline · precomputed" otherwise. */
export async function apiOnline() { return (await api("/readyz", { timeoutMs: 3000 })).ok; }
